"""Structured (JSON-lines) logging for the backend."""

import json
import logging
from datetime import UTC, datetime

_STANDARD_ATTRS = set(logging.makeLogRecord({}).__dict__) | {"message", "asctime"}


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload = {
            "ts": datetime.fromtimestamp(record.created, UTC).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "msg": record.getMessage(),
        }
        # Anything passed via `extra=` becomes a top-level field.
        payload.update({k: v for k, v in record.__dict__.items() if k not in _STANDARD_ATTRS})
        if record.exc_info:
            payload["exc"] = self.formatException(record.exc_info)
        return json.dumps(payload, default=str)


def configure_logging(level: str = "INFO") -> None:
    handler = logging.StreamHandler()
    handler.setFormatter(JsonFormatter())
    root = logging.getLogger()
    root.handlers = [handler]
    root.setLevel(level.upper())

from fastapi import APIRouter
from pydantic import BaseModel

from app.config import APP_NAME, SYNTHETIC_DATA_NOTICE, TAGLINE

router = APIRouter(tags=["health"])


class HealthResponse(BaseModel):
    status: str
    app: str
    tagline: str
    notice: str


@router.get("/health")
def health() -> HealthResponse:
    """Liveness only. Integration health (DB, AI, Chert) arrives in Phases 4-6."""
    return HealthResponse(status="ok", app=APP_NAME, tagline=TAGLINE, notice=SYNTHETIC_DATA_NOTICE)

