@import 'tailwindcss';

@theme {
  --color-surface: #0b1220;
  --color-panel: #111a2e;
  --color-border: #22304d;
  --color-status-normal: #34d399;
  --color-status-pressure: #fbbf24;
  --color-status-breach: #f87171;
}

body {
  margin: 0;
  background: var(--color-surface);
  color: #e5ecf7;
  font-family: Inter, system-ui, 'Segoe UI', sans-serif;
}

export const APP_NAME = 'TriageX'
export const TAGLINE =
  'Every ER capacity tool shows you the problem. TriageX calls the people who can fix it.'
export const SYNTHETIC_DATA_NOTICE =
  'Synthetic hospital operations simulation — not real-time hospital data.'

export interface HealthResponse {
  status: string
  app: string
  tagline: string
  notice: string
}

export async function fetchHealth(signal?: AbortSignal): Promise<HealthResponse> {
  const response = await fetch('/api/health', { signal })
  if (!response.ok) {
    throw new Error(`Backend health check failed (HTTP ${response.status})`)
  }
  return (await response.json()) as HealthResponse
}

import { useEffect, useState } from 'react'
import { fetchHealth } from './services/api'
import { APP_NAME, SYNTHETIC_DATA_NOTICE, TAGLINE } from './types/branding'

type BackendState = 'checking' | 'online' | 'offline'

const BACKEND_LABEL: Record<BackendState, string> = {
  checking: 'Backend: checking…',
  online: 'Backend: online',
  offline: 'Backend: offline',
}

const BACKEND_COLOR: Record<BackendState, string> = {
  checking: 'bg-status-pressure',
  online: 'bg-status-normal',
  offline: 'bg-status-breach',
}

export default function App() {
  const [backend, setBackend] = useState<BackendState>('checking')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()
    fetchHealth(controller.signal)
      .then(() => setBackend('online'))
      .catch((err: unknown) => {
        if (controller.signal.aborted) return
        setBackend('offline')
        setError(err instanceof Error ? err.message : 'Unknown error')
      })
    return () => controller.abort()
  }, [])

  return (
    <div className="min-h-screen">
      <div
        role="note"
        className="bg-status-pressure/15 px-4 py-1.5 text-center text-sm text-status-pressure"
      >
        {SYNTHETIC_DATA_NOTICE}
      </div>
      <header className="flex items-center justify-between border-b border-border bg-panel px-6 py-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">{APP_NAME}</h1>
          <p className="text-sm text-slate-400">{TAGLINE}</p>
        </div>
        <div className="flex items-center gap-2 rounded-full border border-border px-3 py-1 text-sm">
          <span className={`h-2 w-2 rounded-full ${BACKEND_COLOR[backend]}`} />
          <span>{BACKEND_LABEL[backend]}</span>
        </div>
      </header>
      <main className="p-6">
        {error && (
          <p role="alert" className="mb-4 rounded border border-status-breach/50 px-3 py-2 text-sm">
            {error}
          </p>
        )}
        <p className="text-slate-400">
          Repository setup complete. The command-center dashboard is built in Phase 7.
        </p>
      </main>
    </div>
  )
}

import { render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import App from './App'

function mockFetch(impl: () => Promise<Response>) {
  vi.stubGlobal('fetch', vi.fn(impl))
}

afterEach(() => vi.unstubAllGlobals())

describe('App shell', () => {
  it('shows TriageX branding and the synthetic-data notice', async () => {
    mockFetch(async () => new Response(JSON.stringify({ status: 'ok' }), { status: 200 }))
    render(<App />)

    expect(screen.getByRole('heading', { name: 'TriageX' })).toBeInTheDocument()
    expect(screen.getByText(/TriageX calls the people who can fix it/)).toBeInTheDocument()
    expect(screen.getByRole('note')).toHaveTextContent('not real-time hospital data')
    expect(await screen.findByText('Backend: online')).toBeInTheDocument()
  })

  it('shows a visible error when the backend is unreachable', async () => {
    mockFetch(async () => new Response('', { status: 503 }))
    render(<App />)

    expect(await screen.findByText('Backend: offline')).toBeInTheDocument()
    expect(screen.getByRole('alert')).toHaveTextContent('HTTP 503')
  })
})

